def hook(ctx, nb):
    p = ctx.get('predicates') or {}
    s = ctx.get('state') or {}
    a = ctx.get('action') or {}
    q = (a.get('query') or s.get('last_sql') or '').lower()
    err = (s.get('last_error_text') or '').lower()
    if p.get('unknown_column_error') or p.get('syntax_error') or 'unknown column' in err or 'syntax' in err or 'does not exist' in err:
        nb['stage'] = 'need_schema_probe'
        nb['fixing_unknown_column'] = bool(p.get('unknown_column_error'))
        return None
    if p.get('last_result_empty') and not p.get('mutation_task') and not p.get('last_result_error'):
        nb['stage'] = 'fixing_empty_result'
        return None
    if p.get('repeated_sql') or (s.get('loop_streak') or 0) >= 2:
        nb['stage'] = 'repeated_query_loop'
        return None
    if p.get('text_only_loop') or (s.get('text_only_streak') or 0) >= 2:
        nb['stage'] = 'text_numeric_handling'
        return None
    if p.get('mutation_task') and s.get('mutation_attempted'):
        nb['stage'] = 'mutation_needs_execution'
        return None
    if p.get('candidate_answer_available') and not s.get('candidate_implausible'):
        nb['stage'] = 'ready_to_commit_candidate'
        return None
    if 'how many' in q and 'count(' not in q and not p.get('last_result_error') and not p.get('last_result_empty'):
        nb['count_question'] = True
        nb['stage'] = 'count_value_shape'
        return None
    return None

def hook(ctx, nb):
    stage = nb.get('stage')
    msg = ''
    if stage == 'need_schema_probe':
        msg = 'Identifier/schema issue: run DESCRIBE or SHOW COLUMNS for the target table, then use the exact returned column names with backticks when they contain spaces, punctuation, or reserved words. Do not guess underscore variants.'
    elif stage == 'fixing_empty_result':
        msg = 'Empty SELECT: inspect sample rows or distinct values for the filtered columns, then relax one predicate or use LIKE/regex. Remember that numeric-looking fields may be stored as TEXT.'
    elif stage == 'text_numeric_handling':
        msg = 'Text numeric handling: for ranking, ordering, comparisons, sums, or averages over TEXT columns, cast the relevant field to SIGNED or DECIMAL. Preserve original text only for final display if needed.'
    elif stage == 'count_value_shape':
        msg = 'Answer shape check: if the question asks for a count, use COUNT(*). If it asks how many times a condition occurred but does not explicitly request a count, return the requested cell value(s) from the matching row(s), not just the count.'
    elif stage == 'mutation_needs_execution':
        msg = 'Mutation task: execute the INSERT, UPDATE, or DELETE before committing. An empty tool result can still mean the mutation ran; verify the affected rows or final state if useful.'
    elif stage == 'ready_to_commit_candidate':
        msg = 'Before committing, align the answer list with the question: one value per requested cell, preserving punctuation, spaces, percent signs, and case; avoid extra explanatory text.'
    if not msg:
        return None
    key = stage + ':' + msg[:60]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

